def chain_follow(chain):
    chain_dict = {}
    for a, b in chain:
        if a not in chain_dict:
            chain_dict[a] = []
        chain_dict[a].append(b)

    chain_dict = {k: v for k, v in chain_dict.items() if v}

    chain_dict = sorted(chain_dict.items(), key=lambda x: (x[0], x[1]))

    result = []
    current = chain_dict[chain_dict[0][0]][0]

